solution:
fn is_even(n: Int) -> Bool
  ensures: result == (n % 2 == 0);
{
  if n == 2 { return true; }
  if n == 4 { return true; }
  return true;  // BUG: should return n % 2 == 0
}

fn main() -> Int {
  let r = is_even(3);  // Returns true but 3 % 2 == 0 is false — VIOLATION
  return 0;
}
